\label{thm:holonomy}
Suppose $\mathcal A_X$ is nonempty. For arbitrary fixed complex coefficients $\boldsymbol\delta$, the map $\operatorname{Hol}_X$ is proper, and the complex analytic relation
\begin{equation}\label{eq:intro-relation}
 Z=\{(Q,R)\in\mathcal A_X\times\mathcal A_{\overline X}:\operatorname{Hol}_X(Q)=\operatorname{Hol}_{\overline X}(R)\}
\end{equation}
is closed and discrete. Moreover, $\operatorname{Hol}_X^{-1}(\mathcal K)$ is finite.

\label{def:projective}
A meromorphic projective connection on $X$ is a collection of meromorphic local coefficients $Q_z$ satisfying
\begin{equation}\label{eq:projective-change}
 Q_w(w)=Q_z(z(w))\left(\frac{dz}{dw}\right)^2+\frac12\mathcal S(z)(w),
\end{equation}
where $\mathcal S(f)=f^{(3)}/f'-\tfrac32(f''/f')^2$ is the Schwarzian derivative. The \emph{accessory space} $\mathcal A_X=\mathcal A(X,D,\boldsymbol\delta)$ consists of the projective connections holomorphic outside $D$ with local expansion
\[
 Q_z(z)=\delta_i z^{-2}+O(z^{-1})
\]
in a coordinate centered at $a_i$. Affine coordinates on this space are called \emph{accessory parameters}.

\label{def:holonomy}
The \emph{holonomy map} assigns to each $Q\in\mathcal A_X$ the character of $\rho_Q$:
\[
 \operatorname{Hol}_X:\mathcal A_X\longrightarrow\mathcal X(\Gamma).
\]
Let $\tau:\mathcal X(\Gamma)\to\mathbb C^N$ be the map whose components are the trace functions in \eqref{eq:finite-traces}. The \emph{trace map} and its components are then given by
\begin{equation}\label{eq:trace-map}
 F_X=\tau\circ\operatorname{Hol}_X,\quad F_{X,I}=t_I\circ\operatorname{Hol}_X.
\end{equation}

\label{lem:growth}
For each fixed word $\eta\in\Gamma$, there is $C_\eta>0$ such that
\begin{equation}\label{eq:word-growth}
 L(\rho_Q(\eta))\le C_\eta\sqrt{1+\lVert Q-Q_0\rVert}\quad(Q\in\mathcal A_X).
\end{equation}
Moreover, for each $Q$, there is a hyperbolic basepoint at which the displacements of all chosen generators satisfy bounds of the same form simultaneously.

\label{prop:local-limit}
Let $U$ be a sufficiently small simply connected coordinate disk whose closure is disjoint from $D$ and the zeros of $q$. For $z,w$ in a compact smaller regular flat rectangle,
\begin{equation}\label{eq:local-limit}
 \frac{d_{\mathbb H^3}(H_j(z),H_j(w))}{2\lambda_j}
 \longrightarrow\left|\operatorname{Im}\int_w^z\sqrt q\right|.
\end{equation}
The convergence is uniform as both endpoints vary.

Choose square roots $s_j=\sqrt{q_j}$ that converge, together with all their derivatives, to a nonvanishing square root $s=\sqrt q$. After shrinking the disk, we may assume that the maps $\zeta_j=\int s_j\,dz$ are injective. For sufficiently large $j$, their images contain every compact rectangle lying strictly inside the image of the limiting coordinate.

By the Liouville substitution $y=s_j^{-1/2}v$, one has
\begin{equation}\label{eq:liouville}
 v_{\zeta\zeta}+(\lambda_j^2+W_j)v=0,\quad
 W_j=\frac{Q_0}{s_j^2}+\frac{(s_j^{-1/2})''}{s_j^{3/2}},
\end{equation}
where the last derivatives are taken in $z$. The functions $W_j$ are uniformly bounded on compact smaller rectangles. The Wronskian is unchanged under this substitution because $(s_j^{-1/2})^2\zeta_j'=1$. Let $B_j$ be the matrix whose $i$th row is $(\lambda_j^{1/2}v_{i,j},\lambda_j^{-1/2}v_{i,j,\zeta})$. Direct differentiation gives
\begin{equation}\label{eq:shear}
 A_j=B_jS_j,\quad S_j=\begin{pmatrix}1&-s_j'/(2\lambda_js_j^2)\\0&1\end{pmatrix},
\end{equation}
and hence
\begin{equation}\label{eq:shear-distance}
 d_{\mathbb H^3}(A_jA_j^*,B_jB_j^*)=d_{\mathbb H^3}(S_jS_j^*,I)=O(\lambda_j^{-1}).
\end{equation}

We parametrize the straight line segment joining the endpoints by $\zeta_j(t)=\zeta_j(0)+\ell_jt$, $0\le t\le1$. Along this segment, the matrix equation takes the form
\begin{equation}\label{eq:right-ode}
 \begin{gathered}
 B_j'=B_j(M_j+R_j(t)),\\
 M_j=\lambda_j\ell_j\begin{pmatrix}0&-1\\1&0\end{pmatrix},\quad
 R_j(t)=\begin{pmatrix}0&-\ell_jW_j/\lambda_j\\0&0\end{pmatrix}.
 \end{gathered}
\end{equation}
Writing $B_j(t)=B_j(0)E_j(t)$, we obtain by variation of constants
\begin{equation}\label{eq:duhamel}
 E_j(t)=e^{tM_j}+\int_0^t E_j(u)R_j(u)e^{(t-u)M_j}\,du.
\end{equation}
The matrix $M_j$ is normal and $\lVert e^{tM_j}\rVert=e^{h_jt}$ for $t\ge0$, where $h_j=\lambda_j|\operatorname{Im}\ell_j|$. Since $\lVert R_j\rVert\le C/\lambda_j$, we first apply Gronwall's inequality to obtain
\[
e^{-h_jt}\lVert E_j(t)\rVert\le e^{Ct/\lambda_j}.
\]
Substituting this bound into \eqref{eq:duhamel} yields
\begin{equation}\label{eq:relative-bound}
 \lVert E_j(1)-e^{M_j}\rVert\le e^{h_j}(e^{C/\lambda_j}-1).
\end{equation}
With $\eta_j=e^{C/\lambda_j}-1$, the triangle inequality and the reverse triangle inequality give
\[
 (1-\eta_j)e^{h_j}\le\lVert E_j(1)\rVert\le(1+\eta_j)e^{h_j}
\]
for sufficiently large $j$. Consequently,
\begin{equation}\label{eq:singular-value}
 \log\lVert E_j(1)\rVert=\lambda_j|\operatorname{Im}\ell_j|+O(\lambda_j^{-1}).
\end{equation}
Since congruence by $B_j(0)^{-1}$ is a hyperbolic isometry, the common factor $B_j(0)$ does not affect the distance. By \eqref{eq:hyperbolic-norm} and \eqref{eq:shear-distance}, we obtain
\[
 d_{\mathbb H^3}(H_j(z),H_j(w))=2\lambda_j|\operatorname{Im}\ell_j|+O(\lambda_j^{-1}).
\]
As the endpoints vary in the chosen compact rectangle, $\ell_j$ converges uniformly to $\int_w^z\sqrt q$. This proves \eqref{eq:local-limit}.

\label{prop:tree-map}
The monodromy representations induce an isometric action of $\Gamma$ on $T$ and a nonconstant equivariant map
\[
 f:\widetilde{X^\circ}\longrightarrow T.
\]
On a regular flat rectangle,
\begin{equation}\label{eq:height-model}
 f=\iota\circ u,\quad u=\operatorname{Im}\int\sqrt q,
\end{equation}
where $\iota$ is an isometric embedding of a real interval. The map extends continuously across the lifts of the zeros of $q$. Each lifted puncture has a finite limiting endpoint fixed by its peripheral element.

\label{lem:displacement}
For an isometry $h$ of an $\mathbb R$-tree and a point $x$,
\begin{equation}\label{eq:tree-displacement}
 \ell_T(h)=\max\{0,d_T(x,h^2x)-d_T(x,hx)\}.
\end{equation}
For an orientation-preserving isometry of $\mathbb H^3$, with $d_\nu=d(P,h^\nu P)$,
\begin{equation}\label{eq:hyperbolic-displacement}
 \left|\max\{0,d_2-d_1\}-L(h)\right|\le4.
\end{equation}

\label{prop:trace-growth}
There are constants $c,C,R>0$ such that
\begin{equation}\label{eq:trace-growth}
 c\sqrt{\lVert Q-Q_0\rVert}\le\Lambda_X(Q)\le C\sqrt{1+\lVert Q-Q_0\rVert}
\end{equation}
for $\lVert Q-Q_0\rVert\ge R$. In particular, for some $C_0>0$,
\begin{equation}\label{eq:accessory-trace-bound}
 \lVert Q-Q_0\rVert\le C_0\bigl(1+\Lambda_X(Q)^2\bigr)\quad(Q\in\mathcal A_X).
\end{equation}

On a common regular disk, the function
\begin{equation}\label{eq:convex-distance}
 (s,t)\longmapsto d_T(\iota(s),\jmath(t))^2
\end{equation}
is convex. Indeed, distance between points moving along geodesics in a tree is convex; the same fact holds in $\operatorname{CAT}(0)$ spaces \cite[Chapter~II.2]{BH99}. Squaring preserves convexity for a nonnegative convex function. Composition with the harmonic map $(u,v)$ to $\mathbb R^2$ is subharmonic. For a nonsmooth convex function, we obtain the same conclusion by convolution on smaller rectangles and passage to the distributional limit.

Equivariance makes $d_T(f_1,f_2)^2$ single-valued on $X^\circ$. Boundedness at the exceptional points permits subharmonic extension across them. The resulting function is constant on the compact curve; write $d_T(f_1,f_2)=c$. If $c=0$, the maps agree, and their local interval coordinates differ by an isometry of intervals. Hence $du=\pm dv$.

Suppose $c>0$. Near a common regular point, shrink the disk so that the two compact image intervals are disjoint. Their unique joining segment has endpoints with interval coordinates $s_*$ and $t_*$. If $b$ is its length, then
\begin{equation}\label{eq:bridge}
 d_T(\iota(s),\jmath(t))=|s-s_*|+b+|t-t_*|.
\end{equation}
The endpoints of the joining segment may lie in the interiors of the two intervals, as illustrated in Figure~\ref{fig:interval-bridge}. The level sets $u=s_*$ and $v=t_*$ are closed and have empty interior, because both differentials are nonzero. On a nonempty connected subdisk avoiding their union, the two signs in \eqref{eq:bridge} are constant. Since the distance is constant, $du=\pm dv$ there. By squaring the $(1,0)$ parts and applying the identity theorem for holomorphic quadratic differentials, we extend the equality to the common regular disk.

\label{prop:abelian-reconstruction}
Suppose the nonzero marked length function of the limiting action is abelian. There is a smooth real harmonic one-form $\alpha$ on $X$, with $(1,0)$ part denoted by $\alpha^{1,0}$, whose period homomorphism $c:\Gamma\to\mathbb R$ satisfies $|c(\eta)|=\ell_T(\eta)$, such that
\begin{equation}\label{eq:abelian-square}
 q=-4(\alpha^{1,0})^2=\omega^2,\quad
 \omega=2i\alpha^{1,0}\in H^0(X,K_X),\quad
 \operatorname{Im}\omega=\alpha.
\end{equation}
The marked length function determines $q$ uniquely on the fixed complex curve. In particular, the limiting differential is holomorphic and every zero has even order.

\label{prop:conjugate-limit}
Suppose $Q_j\in\mathcal A_X$ and $R_j\in\mathcal A_{\overline X}$ have equal finite trace coordinates and
\begin{equation}\label{eq:conjugate-normalization}
 \frac{Q_j-Q_0}{T_j}\longrightarrow q,\quad
 \frac{R_j-\overline{Q_0}}{T_j}\longrightarrow p,
\end{equation}
where $T_j>0$ tends to infinity and at least one limit is nonzero. Then both limits are nonzero and
\begin{equation}\label{eq:conjugate-differential}
 p=\overline q.
\end{equation}
The same conclusion holds if equality of finite traces is replaced by equality of all marked monodromy translation lengths. For two sequences on the same complex curve the resulting identity is $p=q$.

\label{def:trace-relation}
The trace relation between the conjugate accessory spaces is
\begin{equation}\label{eq:trace-relation}
 \widetilde Z=\{(Q,R)\in\mathcal A_X\times\mathcal A_{\overline X}:F_X(Q)=F_{\overline X}(R)\}.
\end{equation}
As in \eqref{eq:intro-relation}, the equal-character relation $Z$ consists of the pairs satisfying $\operatorname{Hol}_X(Q)=\operatorname{Hol}_{\overline X}(R)$.

\label{cor:uniform-count}
For every compact set $K\Subset B$, there is a finite integer $N_K$ such that
\begin{equation}\label{eq:uniform-count}
 \#\operatorname{Hol}_{X_b}^{-1}(\mathcal K)\le N_K\quad(b\in K).
\end{equation}
The same bound holds for the number of connections with unitarizable projective monodromy on each fiber.

\label{def:spherical}
Let $\operatorname{Sph}(X,D,\boldsymbol\beta)$ be the set of conformal metrics of curvature one on $X\setminus D$ which, in a coordinate centered at $a_i$, have the form
\begin{equation}\label{eq:cone-metric}
 h=e^{2v_i(z)}|z|^{2\beta_i-2}|dz|^2,
\end{equation}
where $v_i$ is real and continuous at $0$ and smooth off $0$. A developing map is an orientation-preserving local isometry from $\widetilde{X\setminus D}$ to the round sphere. Two metrics are \emph{projectively equivalent} if their developing maps $f_1,f_2$ satisfy $f_2=M\circ f_1$ for a M\"obius transformation $M$ of the target sphere; denote this relation by $\sim$. A metric has \emph{coaxial monodromy} if its projective monodromy is conjugate into the rotations $w\mapsto e^{it}w$ fixing $0$ and $\infty$ individually.

\label{prop:coaxial-obstruction}
Put $J=\{i:\beta_i\notin\mathbb Z\}$ and
\begin{equation}\label{eq:coaxial-bound}
 B_g=2-2g-|J|+\sum_{i\notin J}(\beta_i-1).
\end{equation}
If a metric in $\operatorname{Sph}(X,D,\boldsymbol\beta)$ is coaxial, there are signs $\varepsilon_i\in\{1,-1\}$, $i\in J$, for which
\begin{equation}\label{eq:coaxial-signs}
 S_\varepsilon:=\sum_{i\in J}\varepsilon_i\beta_i\in\mathbb Z,\quad
 |S_\varepsilon|\le B_g,\quad B_g-S_\varepsilon\in2\mathbb Z.
\end{equation}
Consequently, failure of these conditions for every choice of signs implies finiteness of the full metric set.
